import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Rate","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/rate.md","filePath":"03-developer/models/rate.md"}`),a={name:`03-developer/models/rate.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="rate" tabindex="-1">Rate <a class="header-anchor" href="#rate" aria-label="Permalink to “Rate”">​</a></h1><p>The <code>Rate</code> model is used to store ratings that users assign to different evaluation criteria. Each record specifies who gave a rating, which entity received it, the evaluation criterion it was given under, and the rating value.</p><h2 id="data-structure" tabindex="-1">Data structure <a class="header-anchor" href="#data-structure" aria-label="Permalink to “Data structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique rating ID</td></tr><tr><td><code>rateable_type</code></td><td>VARCHAR(255)</td><td>No</td><td>Type of the entity that received the rating</td></tr><tr><td><code>rateable_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the entity that received the rating</td></tr><tr><td><code>rater_type</code></td><td>VARCHAR(255)</td><td>No</td><td>Type of the entity that submitted the rating</td></tr><tr><td><code>rater_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the entity that submitted the rating</td></tr><tr><td><code>rate</code></td><td>TINYINT</td><td>No</td><td>Rating value; usually between 1 and 5</td></tr><tr><td><code>evaluation_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the evaluation criterion associated with the rating</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time the rating was submitted</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time of the last update</td></tr></tbody></table><h2 id="relationships" tabindex="-1">Relationships <a class="header-anchor" href="#relationships" aria-label="Permalink to “Relationships”">​</a></h2><ul><li><code>evaluation()</code>: A <code>belongsTo</code> relationship with the <code>Evaluation</code> model; the evaluation criterion associated with this rating.</li></ul><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="evaluation" tabindex="-1"><code>evaluation()</code> <a class="header-anchor" href="#evaluation" aria-label="Permalink to “evaluation()”">​</a></h3><p>Returns the <code>Evaluation</code> model associated with this rating.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li><code>rateable_type</code> and <code>rateable_id</code> specify <strong>what received the rating</strong>. This structure allows different types of entities to be rated.</li><li><code>rater_type</code> and <code>rater_id</code> specify <strong>who submitted the rating</strong>. This structure also supports different types of raters.</li><li>The <code>rate</code> value is usually in the range of 1 to 5; however, the table structure does not show a definitive constraint enforcing this range, so validation depends on the application code.</li><li>Each rating is associated with a specific <code>Evaluation</code>. Because of the <code>RESTRICT</code> foreign key constraint, that evaluation cannot be deleted while related ratings exist.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};